<?php
declare(strict_types=1);
require_once __DIR__.'/Support/ReviewedLocalFixture.php';
use DigiForge\REST\ReviewedContractsController;
final class ReviewedContractsControllerTest extends WP_UnitTestCase {
 private array $actors;
 private ReviewedContractsController $controller;
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();$this->actors=ReviewedLocalFixture::actors();$this->controller=new ReviewedContractsController();}
 private function request(string $method='POST',array $body=[],string $kind='policy',string $shop='digital'):WP_REST_Request {$r=new WP_REST_Request($method,'/digiforge/v1/reviewed-contracts/'.$shop.'/'.$kind);$r->set_url_params(['shop'=>$shop,'kind'=>$kind]);if($method==='POST'){$r->set_header('Content-Type','application/json');$r->set_header('X-WP-Nonce',wp_create_nonce('wp_rest'));$r->set_body(wp_json_encode($body));}return $r;}
 private function proposal():array {return ['input'=>['environment'=>'production','scope'=>'SHOP','workflow'=>'','capability'=>'research','enabled'=>true],'effective_at'=>time()-1,'expires_at'=>time()+3600,'request_id'=>wp_generate_uuid4(),'expected_revision'=>0];}
 public function testPolicyLifecycleIsLocalAndRequiresIndependentReview():void {$created=$this->controller->propose($this->request('POST',$this->proposal()));self::assertInstanceOf(WP_REST_Response::class,$created);$p=$created->get_data();self::assertFalse($p['external_execution_authorized']);$d=['key'=>$p['policy_key'],'expected_revision'=>$p['revision'],'proposal_hash'=>$p['proposal_hash'],'decision'=>'APPROVED','request_id'=>wp_generate_uuid4()];self::assertWPError($this->controller->decide($this->request('POST',$d)));wp_set_current_user($this->actors['reviewer']);$approved=$this->controller->decide($this->request('POST',$d));self::assertInstanceOf(WP_REST_Response::class,$approved);$read=$this->request('GET');$read->set_query_params(['key'=>$p['policy_key']]);self::assertSame('APPROVED',$this->controller->read($read)->get_data()['status']);}
 public function testAnonymousForeignAndNonceFreeWritesDeny():void {$r=$this->request('POST',$this->proposal());$r->set_header('X-WP-Nonce','');self::assertWPError($this->controller->propose($r));self::assertWPError($this->controller->propose($this->request('POST',$this->proposal(),'policy','jewelry')));wp_set_current_user(0);self::assertWPError($this->controller->propose($this->request('POST',$this->proposal())));}
 public function testRejectsUnknownFieldsCoercionSecretsAndOversizeBodies():void {foreach([['expected_revision'=>'0'],['effective_at'=>(string)time()],['token'=>'secret'],['input'=>['enabled'=>1]]] as $change)self::assertWPError($this->controller->propose($this->request('POST',array_replace($this->proposal(),$change))));$r=$this->request('POST');$r->set_body(str_repeat(' ',32769));self::assertWPError($this->controller->propose($r));}
 public function testReadRequiresExactQueryAndExplicitShop():void {$r=$this->request('GET');$r->set_query_params(['key'=>'production:SHOP::research','extra'=>'x']);self::assertWPError($this->controller->read($r));$r=$this->request('GET',[],'policy','jewelry');$r->set_query_params(['key'=>'production:SHOP::research']);self::assertWPError($this->controller->read($r));}
 public function testExactPlainPermalinkRoutingMetadataIsAllowedButCannotOverrideScope():void {$r=$this->request('POST',$this->proposal());$r->set_query_params(['rest_route'=>$r->get_route()]);self::assertInstanceOf(WP_REST_Response::class,$this->controller->propose($r));$r=$this->request('GET');$r->set_query_params(['rest_route'=>$r->get_route(),'key'=>'production:SHOP::research']);self::assertInstanceOf(WP_REST_Response::class,$this->controller->read($r));$r->set_query_params(['rest_route'=>'/digiforge/v1/reviewed-contracts/jewelry/policy','key'=>'production:SHOP::research']);self::assertWPError($this->controller->read($r));}
 public function testOwnershipInputUsesOnlyTypedExistingDependencyIdentifiers():void {$p=$this->proposal();$p['input']=['integration_id'=>'1','provider_mapping_id'=>1,'production_template_id'=>1,'source_sha256'=>str_repeat('a',64),'evidence_reference'=>'local://fixture'];self::assertWPError($this->controller->propose($this->request('POST',$p,'ownership')));$p['input']['integration_id']=1;$p['input']['account_reference']='invented';self::assertWPError($this->controller->propose($this->request('POST',$p,'ownership')));}
}
